package dev.hnswforge.util;

import java.util.SplittableRandom;
import java.util.Objects;

/**
 * Deterministic synthetic vector generators used by tests and benchmarks.
 *
 * <p>Clustered data is generated by drawing cluster centers uniformly in
 * {@code [-1, 1]} and adding Gaussian noise around a randomly chosen center.
 * The same seed always produces the same corpus.
 *
 * <p>Thread-safety: all methods are stateless and safe for concurrent use.
 */
public final class SyntheticData {

    private static final double DEFAULT_NOISE = 0.3;

    private SyntheticData() {
    }

    /**
     * Generates {@code count} vectors clustered around {@code clusterCount} centers
     * with the default noise level of 0.3.
     *
     * @param count        number of vectors, must be positive
     * @param dimension    vector dimension, must be positive
     * @param clusterCount number of clusters, must be positive and at most {@code count}
     * @param seed         seed for the deterministic generator
     * @return a new array of new vectors
     * @throws IllegalArgumentException if any size constraint is violated
     */
    public static float[][] clusters(int count, int dimension, int clusterCount, long seed) {
        return clusters(count, dimension, clusterCount, seed, DEFAULT_NOISE);
    }

    /**
     * Generates {@code count} vectors clustered around {@code clusterCount} centers.
     *
     * @param count        number of vectors, must be positive
     * @param dimension    vector dimension, must be positive
     * @param clusterCount number of clusters, must be positive and at most {@code count}
     * @param seed         seed for the deterministic generator
     * @param noise        standard deviation of Gaussian noise around each center, must be positive
     * @return a new array of new vectors
     * @throws IllegalArgumentException if any size constraint is violated
     */
    public static float[][] clusters(int count, int dimension, int clusterCount,
                                     long seed, double noise) {
        if (count <= 0 || dimension <= 0 || clusterCount <= 0 || clusterCount > count
                || noise <= 0.0) {
            throw new IllegalArgumentException(
                    "require count > 0, dimension > 0, 0 < clusterCount <= count and noise > 0");
        }
        SplittableRandom random = new SplittableRandom(seed);
        float[][] centers = new float[clusterCount][dimension];
        for (float[] center : centers) {
            for (int i = 0; i < dimension; i++) {
                center[i] = (float) (random.nextDouble() * 2.0 - 1.0);
            }
        }
        float[][] vectors = new float[count][dimension];
        for (float[] vector : vectors) {
            float[] center = centers[random.nextInt(clusterCount)];
            for (int i = 0; i < dimension; i++) {
                vector[i] = (float) (center[i] + random.nextGaussian() * noise);
            }
        }
        return vectors;
    }

    /**
     * Generates {@code count} vectors uniformly distributed in {@code [0, 1)}^dimension.
     *
     * @param count     number of vectors, must be positive
     * @param dimension vector dimension, must be positive
     * @param seed      seed for the deterministic generator
     * @return a new array of new vectors
     * @throws IllegalArgumentException if a size constraint is violated
     */
    public static float[][] uniform(int count, int dimension, long seed) {
        if (count <= 0 || dimension <= 0) {
            throw new IllegalArgumentException("count and dimension must be positive");
        }
        SplittableRandom random = new SplittableRandom(seed);
        float[][] vectors = new float[count][dimension];
        for (float[] vector : vectors) {
            for (int i = 0; i < dimension; i++) {
                vector[i] = (float) random.nextDouble();
            }
        }
        return vectors;
    }

    /**
     * Generates {@code count} queries near randomly chosen corpus vectors.
     *
     * @param base    corpus used to select query anchors
     * @param count   number of queries, must be positive
     * @param seed    seed for the deterministic generator
     * @return a new array of new query vectors
     * @throws IllegalArgumentException if inputs are invalid
     */
    public static float[][] queries(float[][] base, int count, long seed) {
        Objects.requireNonNull(base, "base must not be null");
        if (base.length == 0 || count <= 0) {
            throw new IllegalArgumentException("base must be non-empty and count must be positive");
        }
        SplittableRandom random = new SplittableRandom(seed);
        float[][] queries = new float[count][];
        for (int i = 0; i < count; i++) {
            float[] source = base[random.nextInt(base.length)];
            float[] query = source.clone();
            for (int j = 0; j < query.length; j++) {
                query[j] += (float) (random.nextGaussian() * 0.05);
            }
            queries[i] = query;
        }
        return queries;
    }
}
